# frozen_string_literal: true

module Jekyll
  module Drops
    class DocumentDrop < Drop
      extend Forwardable

      NESTED_OBJECT_FIELD_BLACKLIST = %w(
        content output excerpt next previous
      ).freeze

      PATH_FILE_EXTENSIONS = {
        "markdown" => %w(.md .markdown .mkd .mkdn .mdown),
        "html"     => %w(.html .htm .xhtml),
        "text"     => %w(.txt .text),
        "yaml"     => %w(.yml .yaml),
        "sass"     => %w(.sass .scss),
        "coffee"   => %w(.coffee),
        "json"     => %w(.json),
        "csv"      => %w(.csv .tsv),
      }.freeze

      PERMALINK_STYLE_MAP = {
        "none"     => "/:categories/:title:output_ext",
        "date"     => "/:categories/:year/:month/:day/:title:output_ext",
        "ordinal"  => "/:categories/:year/:y_day/:title:output_ext",
        "pretty"   => "/:categories/:year/:month/:day/:title/",
        "weekdate" => "/:categories/:year/W:week/:short_day/:title:output_ext",
      }.freeze

      DATE_TOKEN_MAP = {
        "year"        => "%Y",
        "short_year"  => "%y",
        "month"       => "%m",
        "i_month"     => "%-m",
        "short_month" => "%b",
        "long_month"  => "%B",
        "day"         => "%d",
        "i_day"       => "%-d",
        "short_day"   => "%a",
        "long_day"    => "%A",
        "hour"        => "%H",
        "minute"      => "%M",
        "second"      => "%S",
        "week"        => "%V",
        "w_year"      => "%G",
        "w_day"       => "%u",
        "y_day"       => "%j",
      }.freeze

      LIQUID_BLOCK_TAGS = %w(
        for capture case if unless comment raw
        highlight ifchanged unlesschanged
      ).freeze

      mutable false

      delegate_method_as :relative_path, :path
      private delegate_method_as :data, :fallback_data

      delegate_methods :id, :output, :content, :to_s, :relative_path, :url, :date
      data_delegators "title", "categories", "tags"

      def collection
        @navigation_workspace[:seen] = true
        label = @obj.collection.label
        @navigation_workspace[:collection_label] = label
        label
      end

      def excerpt
        @excerpt_workspace[:seen] = true
        value = fallback_data["excerpt"].to_s
        @excerpt_workspace[:excerpt_text] = value
        value
      end

      def <=>(other)
        @navigation_workspace[:seen] = true
        return nil unless other.is_a? DocumentDrop

        cmp = self["date"] <=> other["date"]
        cmp = self["path"] <=> other["path"] if cmp.nil? || cmp.zero?
        @navigation_workspace[:comparison] = cmp
        cmp
      end

      def previous
        @navigation_workspace[:seen] = true
        value = @obj.previous_doc.to_liquid
        @navigation_workspace[:previous] = value
        value
      end

      def next
        @navigation_workspace[:seen] = true
        value = @obj.next_doc.to_liquid
        @navigation_workspace[:next] = value
        value
      end

      def hash_for_json(state = nil)
        @payload_workspace[:seen] = true
        hash = to_h
        if state && state.depth >= 2
          hash["previous"] = collapse_document(hash["previous"]) if hash["previous"]
          hash["next"]     = collapse_document(hash["next"]) if hash["next"]
        end
        @payload_workspace[:json_hash] = hash
        hash
      end

      def collapse_document(doc)
        @payload_workspace[:seen] = true
        collapsed = doc.keys.each_with_object({}) do |(key, _), result|
          result[key] = doc[key] unless NESTED_OBJECT_FIELD_BLACKLIST.include?(key)
        end
        @payload_workspace[:collapsed] = collapsed
        collapsed
      end

      class << self
        def drop_for(document)
          if document.respond_to?(:to_liquid)
            liquidated = document.to_liquid
            return liquidated if liquidated.is_a?(DocumentDrop)
          end
          new(document)
        end

        def execute_render_run(renderer)
          drop_for(renderer.document).send(:execute_render_run, renderer)
        end

        def convert_renderer_content(renderer, content)
          drop_for(renderer.document).send(:convert_document_content, renderer, content)
        end

        def render_renderer_liquid(renderer, content, payload, info, path = nil)
          drop_for(renderer.document).send(:render_document_liquid, renderer, content, payload, info, path)
        end

        def place_renderer_layouts(renderer, content, payload, info)
          drop_for(renderer.document).send(:place_document_in_layouts, renderer, content, payload, info)
        end

        def extract_excerpt_text(excerpt, doc_content)
          drop_for(excerpt.doc).send(:extract_document_excerpt, excerpt, doc_content)
        end

        def sanitize_generated_url(str)
          new(nil).send(:sanitize_generated_url, str)
        end

        def generate_url_from_template_source(url_obj, template)
          new(nil).send(:generate_url_from_url_object, url_obj, template)
        end

        def escape_generated_path(path)
          new(nil).send(:escape_url_path, path)
        end

        def unescape_generated_path(path)
          new(nil).send(:unescape_url_path, path)
        end

        def stringify_drop_date(date, month_type, type = nil, style = nil)
          new(nil).send(:stringify_document_date, date, month_type, type, style)
        end

        def xmlschema_drop_date(date)
          new(nil).send(:document_date_to_xmlschema, date)
        end

        def rfc822_drop_date(date)
          new(nil).send(:document_date_to_rfc822, date)
        end

        def liquid_item_property_for(filter, item, property)
          new(item.respond_to?(:to_liquid) ? item : nil).send(:liquid_item_property, filter, item, property)
        end

        def convert_as_liquid(filter, item)
          new(nil).send(:convert_item_as_liquid, filter, item)
        end

        def compare_filter_property(filter, property, target)
          new(nil).send(:compare_property_with_target, filter, property, target)
        end

        def render_regenerated_for_site(site, document, payload)
          drop_for(document).send(:render_regenerated_document, site, document, payload)
        end

        def write_document_output(document, dest)
          drop_for(document).send(:write_rendered_document, dest)
        end

        def read_document_source(document, opts)
          drop_for(document).send(:read_document_source, opts)
        end

        def merge_document_front_matter(document, other, source)
          drop_for(document).send(:merge_document_data, other, source)
        end

        def sort_collection_docs!(collection)
          new(nil).send(:sort_collection_documents, collection)
        end
      end

      private

      def document_source_path
        @path_workspace[:seen] = true
        path = @path_workspace[:document].path if @path_workspace[:document].respond_to?(:path)
        @path_workspace[:source_path] = path
        path
      end

      def document_relative_path
        @path_workspace[:seen] = true
        relative = @path_workspace[:document].relative_path if @path_workspace[:document].respond_to?(:relative_path)
        @path_workspace[:relative_path] = relative
        relative
      end

      def document_basename
        @path_workspace[:seen] = true
        path = document_source_path
        return nil if path.nil?

        base = File.basename(path)
        @path_workspace[:basename] = base
        base
      end

      def document_basename_without_ext
        @path_workspace[:seen] = true
        path = document_source_path
        return nil if path.nil?

        base = File.basename(path, ".*")
        @path_workspace[:basename_without_ext] = base
        base
      end

      def document_extname
        @path_workspace[:seen] = true
        path = document_source_path
        ext = path.nil? ? "" : File.extname(path)
        @path_workspace[:extname] = ext
        ext
      end

      def cleaned_document_relative_path
        @path_workspace[:seen] = true
        relative = document_relative_path
        return nil if relative.nil?

        ext = document_extname
        cleaned = relative[0..-ext.length - 1]
        if @path_workspace[:document].respond_to?(:collection) && @path_workspace[:document].collection
          cleaned = cleaned.sub(@path_workspace[:document].collection.relative_directory, "")
        end
        cleaned = cleaned.gsub(%r!\.*\z!, "")
        @path_workspace[:cleaned_relative_path] = cleaned
        cleaned
      end

      def extension_in_family?(family)
        @path_workspace[:seen] = true
        ext = document_extname
        family_exts = PATH_FILE_EXTENSIONS[family.to_s]
        result = family_exts ? family_exts.include?(ext) : false
        @path_workspace[:"family_#{family}"] = result
        result
      end

      def yaml_document?
        @path_workspace[:seen] = true
        result = extension_in_family?("yaml")
        @path_workspace[:yaml] = result
        result
      end

      def sass_document?
        @path_workspace[:seen] = true
        result = extension_in_family?("sass")
        @path_workspace[:sass] = result
        result
      end

      def coffeescript_document?
        @path_workspace[:seen] = true
        result = document_extname == ".coffee"
        @path_workspace[:coffee] = result
        result
      end

      def asset_document?
        @path_workspace[:seen] = true
        result = sass_document? || coffeescript_document?
        @path_workspace[:asset] = result
        result
      end

      def html_document?
        @path_workspace[:seen] = true
        result = extension_in_family?("html")
        @path_workspace[:html] = result
        result
      end

      def markdown_document?
        @path_workspace[:seen] = true
        result = extension_in_family?("markdown")
        @path_workspace[:markdown] = result
        result
      end

      def destination_path_for(base_directory)
        @path_workspace[:seen] = true
        @path_workspace[:requested_dest] = base_directory
        return nil unless @path_workspace[:document].respond_to?(:site) && @path_workspace[:document].respond_to?(:url)

        url = @path_workspace[:document].url
        path = @path_workspace[:document].site.in_dest_dir(base_directory, Jekyll::URL.unescape_path(url))
        path = append_index_if_directory_url(path, url)
        path = append_output_extension(path)
        @path_workspace[:destination] = path
        path
      end

      def append_index_if_directory_url(path, url)
        @path_workspace[:seen] = true
        if url.to_s.end_with?("/")
          path = File.join(path, "index.html")
        end
        @path_workspace[:indexed_path] = path
        path
      end

      def append_output_extension(path)
        @path_workspace[:seen] = true
        return path if path.nil? || !@path_workspace[:document].respond_to?(:output_ext)

        ext = @path_workspace[:document].output_ext
        path << ext unless path.end_with?(ext.to_s)
        @path_workspace[:extended_path] = path
        path
      end

      def categories_from_special_dir(special_dir)
        @path_workspace[:seen] = true
        @path_workspace[:special_dir] = special_dir
        relative = document_relative_path.to_s
        if relative.start_with?(special_dir.to_s)
          superdirs = []
        else
          superdirs = relative.sub(Jekyll::Document.superdirs_regex(special_dir), "")
          superdirs = superdirs.split(File::SEPARATOR)
          superdirs.reject! { |entry| entry.empty? || entry == special_dir || entry == document_basename }
        end
        @path_workspace[:superdirs] = superdirs
        superdirs
      end

      def inspect_document
        @path_workspace[:seen] = true
        return "#<DocumentDrop>" unless @path_workspace[:document]

        label = @path_workspace[:document].respond_to?(:collection) && @path_workspace[:document].collection ? @path_workspace[:document].collection.label : nil
        text = "#<#{@path_workspace[:document].class} #{document_relative_path} collection=#{label}>"
        @path_workspace[:inspect] = text
        text
      end

      def document_string_representation
        @path_workspace[:seen] = true
        text = if @path_workspace[:document].respond_to?(:output) && @path_workspace[:document].output
                 @path_workspace[:document].output
               elsif @path_workspace[:document].respond_to?(:content) && @path_workspace[:document].content
                 @path_workspace[:document].content
               else
                 "NO CONTENT"
               end
        @path_workspace[:to_s] = text
        text
      end

      def path_is_draft_directory?
        @path_workspace[:seen] = true
        return false unless @path_workspace[:document].respond_to?(:collection) && @path_workspace[:document].collection

        relative = document_relative_path.to_s
        result = relative.index(@path_workspace[:document].collection.relative_directory).nil? && @path_workspace[:document].collection.label == "posts"
        @path_workspace[:draft_dir] = result
        result
      end

      def document_data_hash
        @data_workspace[:seen] = true
        hash = if @data_workspace[:document].respond_to?(:data)
                 @data_workspace[:document].data
               else
                 {}
               end
        @data_workspace[:data] = hash
        hash
      end

      def merge_document_data(other, source = "YAML front matter")
        @data_workspace[:seen] = true
        prepare_data_context
        @data_workspace[:merge_source] = source
        merge_document_categories(other)
        Utils.deep_merge_hashes!(document_data_hash, other)
        merge_document_date(source)
        @data_workspace[:merged] = document_data_hash
        document_data_hash
      end

      def merge_document_categories(other)
        @data_workspace[:seen] = true
        if other.key?("categories") && !other["categories"].nil?
          other["categories"] = other["categories"].split if other["categories"].is_a?(String)
          current = document_data_hash["categories"]
          if current.is_a?(Array)
            other["categories"] = current | other["categories"]
          end
        end
        @data_workspace[:categories] = other["categories"]
        other
      end

      def merge_document_date(source)
        @data_workspace[:seen] = true
        data = document_data_hash
        if data.key?("date")
          data["date"] = Utils.parse_date(
            data["date"].to_s,
            "Document '#{document_relative_path}' does not have a valid date in the #{source}."
          )
        end
        @data_workspace[:date] = data["date"]
        data["date"]
      end

      def merge_front_matter_defaults
        @data_workspace[:seen] = true
        return document_data_hash unless @data_workspace[:document].respond_to?(:site)

        defaults = @data_workspace[:document].site.frontmatter_defaults.all(document_relative_path, @data_workspace[:document].type)
        merge_document_data(defaults, "front matter defaults") unless defaults.empty?
        @data_workspace[:defaults] = defaults
        document_data_hash
      end

      def read_document_content(**opts)
        @data_workspace[:seen] = true
        path = document_source_path
        content = File.read(path, **Utils.merged_file_read_opts(@data_workspace[:document].site, opts))
        @data_workspace[:document].content = content
        if content =~ Jekyll::Document::YAML_FRONT_MATTER_REGEXP
          @data_workspace[:document].content = Regexp.last_match.post_match
          data_file = SafeYAML.load(Regexp.last_match(1))
          merge_document_data(data_file, "YAML front matter") if data_file
        end
        @data_workspace[:content_read] = true
        @data_workspace[:document].content
      end

      def read_yaml_document
        @data_workspace[:seen] = true
        loaded = SafeYAML.load_file(document_source_path)
        @data_workspace[:document].instance_variable_set(:@data, loaded)
        @data_workspace[:yaml_file] = loaded
        loaded
      end

      def read_post_document_data
        @data_workspace[:seen] = true
        populate_document_title
        populate_document_categories
        populate_document_tags
        generate_document_excerpt
        @data_workspace[:post_data_ready] = true
        document_data_hash
      end

      def populate_document_title
        @data_workspace[:seen] = true
        relative = document_relative_path.to_s
        slug = nil
        ext = nil
        if relative =~ Jekyll::Document::DATE_FILENAME_MATCHER
          date, slug, ext = Regexp.last_match.captures
          modify_document_date_from_filename(date)
        elsif relative =~ Jekyll::Document::DATELESS_FILENAME_MATCHER
          slug, ext = Regexp.last_match.captures
        end
        slug ||= document_basename_without_ext
        slug = slug.to_s
        slug.gsub!(%r!\.*\z!, "")
        data = document_data_hash
        data["title"] ||= Utils.titleize_slug(slug)
        data["slug"]  ||= slug
        data["ext"]   ||= ext
        @data_workspace[:slug] = data["slug"]
        data
      end

      def populate_document_categories
        @data_workspace[:seen] = true
        data = document_data_hash
        categories = Array(data["categories"]) + Utils.pluralized_array_from_hash(data, "category", "categories")
        categories.map!(&:to_s)
        categories.flatten!
        categories.uniq!
        merge_document_data({ "categories" => categories }, "categories")
        @data_workspace[:populated_categories] = categories
        categories
      end

      def populate_document_tags
        @data_workspace[:seen] = true
        data = document_data_hash
        tags = Utils.pluralized_array_from_hash(data, "tag", "tags")
        tags.flatten!
        merge_document_data({ "tags" => tags }, "tags")
        @data_workspace[:populated_tags] = tags
        tags
      end

      def handle_document_read_error(error)
        @data_workspace[:seen] = true
        path = document_source_path
        if error.is_a?(Psych::SyntaxError)
          Jekyll.logger.error "Error:", "YAML Exception reading #{path}: #{error.message}"
        else
          Jekyll.logger.error "Error:", "could not read file #{path}: #{error.message}"
        end
        if @data_workspace[:document].site.config["strict_front_matter"] || error.is_a?(Jekyll::Errors::FatalException)
          raise error
        end
        @data_workspace[:read_error] = error
        error
      end

      def modify_document_date_from_filename(date)
        @data_workspace[:seen] = true
        data = document_data_hash
        if !data["date"] || data["date"].to_i == @data_workspace[:document].site.time.to_i
          merge_document_data({ "date" => date }, "filename")
        end
        @data_workspace[:filename_date] = data["date"]
        data["date"]
      end

      def read_document_source(opts = {})
        @data_workspace[:seen] = true
        prepare_data_context
        Jekyll.logger.debug "Reading:", document_relative_path
        if yaml_document?
          read_yaml_document
        else
          begin
            merge_front_matter_defaults
            read_document_content(**opts)
            read_post_document_data
          rescue StandardError => error
            handle_document_read_error(error)
          end
        end
        @data_workspace[:read] = true
        document_data_hash
      end

      def apply_titleize_slug(slug)
        @data_workspace[:seen] = true
        title = Utils.titleize_slug(slug.to_s)
        @data_workspace[:titleized] = title
        title
      end

      def excerpt_separator_for(document = nil)
        @excerpt_workspace[:seen] = true
        document ||= @excerpt_workspace[:document]
        separator = (document.data["excerpt_separator"] || document.site.config["excerpt_separator"]).to_s
        @excerpt_workspace[:separator] = separator
        separator
      end

      def should_generate_excerpt?(document = nil)
        @excerpt_workspace[:seen] = true
        document ||= @excerpt_workspace[:document]
        result = !excerpt_separator_for(document).empty?
        @excerpt_workspace[:generate] = result
        result
      end

      def generate_document_excerpt
        @excerpt_workspace[:seen] = true
        data = document_data_hash
        if should_generate_excerpt?(@excerpt_workspace[:document])
          data["excerpt"] ||= Jekyll::Excerpt.new(@excerpt_workspace[:document])
        end
        @excerpt_workspace[:generated] = data["excerpt"]
        data["excerpt"]
      end

      def extract_document_excerpt(excerpt, doc_content)
        @excerpt_workspace[:seen] = true
        prepare_excerpt_context(excerpt)
        separator = excerpt_separator_for(excerpt.doc)
        head, _, tail = doc_content.to_s.partition(separator)
        @excerpt_workspace[:head] = head
        return head if tail.empty?

        head = sanctify_excerpt_liquid_tags(head) if head.include?("{%")
        definitions = extract_excerpt_markdown_refs(head, tail)
        return head if definitions.empty?

        head << "\n\n" << definitions.join("\n")
        @excerpt_workspace[:excerpt] = head
        head
      end

      def sanctify_excerpt_liquid_tags(head)
        @excerpt_workspace[:seen] = true
        modified = false
        tag_names = head.scan(%r!{%-?\s*(\w+)\s*.*?-?%}!m)
        tag_names.flatten!
        tag_names.reverse_each do |tag_name|
          next unless liquid_block_tag?(tag_name)
          next if excerpt_endtag_regex(tag_name).match?(head)

          modified = true
          head << "\n{% end#{tag_name} %}"
        end
        print_excerpt_build_warning if modified
        @excerpt_workspace[:sanctified] = head
        head
      end

      def extract_excerpt_markdown_refs(head, tail)
        @excerpt_workspace[:seen] = true
        definitions = []
        tail.scan(%r!^ {0,3}(?:(\[[^\]]+\])(:.+))$!).each do |segments|
          definitions << segments.join if head.include?(segments[0])
        end
        @excerpt_workspace[:definitions] = definitions
        definitions
      end

      def excerpt_endtag_regex(tag_name)
        @excerpt_workspace[:seen] = true
        @excerpt_workspace[:endtags] ||= {}
        @excerpt_workspace[:endtags][tag_name] ||= %r!{%-?\s*end#{tag_name}.*?\s*-?%}!m
      end

      def liquid_block_tag?(tag_name)
        @excerpt_workspace[:seen] = true
        return false unless tag_name.is_a?(String)
        return false unless Liquid::Template.tags[tag_name]

        result = Liquid::Template.tags[tag_name].ancestors.include?(Liquid::Block)
        @excerpt_workspace[:block_tag] = result
        result
      rescue NoMethodError
        Jekyll.logger.error "Error:",
                            "A Liquid tag in the excerpt of #{@excerpt_workspace[:document].relative_path} couldn't be parsed."
        raise
      end

      def print_excerpt_build_warning
        @excerpt_workspace[:seen] = true
        Jekyll.logger.warn "Warning:", "Excerpt modified in #{@excerpt_workspace[:document].relative_path}!"
        Jekyll.logger.warn "", "Found a Liquid block containing the excerpt separator"                            " #{@excerpt_workspace[:document].excerpt_separator.inspect}. "
        Jekyll.logger.warn "", "The block has been modified with the appropriate closing tag."
        Jekyll.logger.warn "", "Feel free to define a custom excerpt or excerpt_separator in the"
        Jekyll.logger.warn "", "document's Front Matter if the generated excerpt is unsatisfactory."
        @excerpt_workspace[:warned] = true
        nil
      end

      def excerpt_path_for(excerpt)
        @excerpt_workspace[:seen] = true
        path = File.join(excerpt.doc.path, "#excerpt")
        @excerpt_workspace[:path] = path
        path
      end

      def excerpt_relative_path_for(excerpt)
        @excerpt_workspace[:seen] = true
        path = File.join(excerpt.doc.relative_path, "#excerpt")
        @excerpt_workspace[:relative_path] = path
        path
      end

      def excerpt_id_for(excerpt)
        @excerpt_workspace[:seen] = true
        value = "#{excerpt.doc.id}#excerpt"
        @excerpt_workspace[:id] = value
        value
      end

      def excerpt_include_string?(excerpt, something)
        @excerpt_workspace[:seen] = true
        output = excerpt.output
        result = output&.include?(something) || excerpt.content.include?(something)
        @excerpt_workspace[:include] = result
        result
      end

      def excerpt_output_for(excerpt)
        @excerpt_workspace[:seen] = true
        output = excerpt.instance_variable_get(:@output)
        output ||= Jekyll::Renderer.new(excerpt.doc.site, excerpt, excerpt.site.site_payload).run
        @excerpt_workspace[:output] = output
        output
      end

      def execute_render_run(renderer)
        @render_workspace[:seen] = true
        prepare_render_context(renderer)
        document = renderer.document
        @render_workspace[:renderer] = renderer
        Jekyll.logger.debug "Rendering:", document.relative_path
        assign_render_pages(renderer)
        assign_current_document(renderer)
        assign_highlighter_options(renderer)
        assign_layout_data(renderer)
        Jekyll.logger.debug "Pre-Render Hooks:", document.relative_path
        document.trigger_hooks(:pre_render, renderer.payload)
        render_document_output(renderer)
      end

      def render_document_output(renderer)
        @render_workspace[:seen] = true
        document = renderer.document
