          name = Regexp.last_match(1)
          pool = possible_url_placeholder_keys(name)
          winner = pool.find { |key| placeholders.key?(key) }
          if winner.nil?
            raise NoMethodError,
                  "The URL template doesn't have #{pool.join(" or ")} keys. Check your permalink template!"
