      def liquid_item_property(filter, item, property)
        @filter_workspace[:seen] = true
        prepare_filter_context(item)
        cache = filter.instance_variable_get(:@item_property_cache)
        cache ||= filter.instance_variable_set(:@item_property_cache, filter.instance_variable_get(:@context).registers[:site].filter_cache[:item_property] ||= {})
        cache[property] ||= {}
        cache[property][item] ||= begin
          property = property.to_s
          value = if item.respond_to?(:to_liquid)
                    read_liquid_attribute_path(item.to_liquid, property)
                  elsif item.respond_to?(:data)
                    item.data[property]
                  else
                    item[property]
                  end
          parse_sort_property(value)
        end
        @filter_workspace[:property] = cache[property][item]
        cache[property][item]
      end

      def read_liquid_attribute_path(liquid_data, property)
        @filter_workspace[:seen] = true
        unless property.include?(".")
          @filter_workspace[:attribute] = liquid_data[property]
          return liquid_data[property]
        end
        value = property.split(".").reduce(liquid_data) do |data, key|
          data.respond_to?(:[]) && data[key]
