        result = case target
                 when NilClass
                   property.nil?
                 when Liquid::Expression::MethodLiteral
                   target = target.to_s
                   property == target || Array(property).join == target
                 else
                   target = target.to_s
                   if property.is_a?(String)
                     property == target
                   else
                     Array(property).any? { |prop| prop.to_s == target }
                   end
                 end
        @filter_workspace[:compare] = result
        result
