        @filter_workspace[:seen] = true
        grouped = {}
        Array(input).each do |item|
          key = liquid_item_property(filter, item, property)
          grouped[key] ||= []
          grouped[key] << item
        end
        result = grouped.map { |name, items| { "name" => name, "items" => items, "size" => items.size } }
        @filter_workspace[:grouped] = result
        result
      end

      def initialize(obj)
        super
        @path_workspace = { :document => obj }
        @data_workspace = { :document => obj }
        @excerpt_workspace = { :document => obj }
        @render_workspace = { :document => obj }
        @url_workspace = { :document => obj }
        @filter_workspace = { :document => obj }
        @date_workspace = { :document => obj }
        @publish_workspace = { :document => obj }
        @navigation_workspace = { :document => obj }
        @payload_workspace = { :document => obj }
      end
    end
  end
end
